inline std::wstring RegistryText(const std::wstring&key,const wchar_t*name){DWORD size=0;if(RegGetValueW(HKEY_CURRENT_USER,key.c_str(),name,RRF_RT_REG_SZ,nullptr,nullptr,&size))return {};std::wstring value(size/2,L'\0');if(RegGetValueW(HKEY_CURRENT_USER,key.c_str(),name,RRF_RT_REG_SZ,nullptr,value.data(),&size))return {};while(!value.empty()&&!value.back())value.pop_back();return value;}
