inline bool DllInUse(const std::wstring&path){auto processes=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(processes==INVALID_HANDLE_VALUE)return true;PROCESSENTRY32W process{};process.dwSize=sizeof(process);bool busy=false;if(Process32FirstW(processes,&process))do{if(process.th32ProcessID==GetCurrentProcessId())continue;auto modules=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,process.th32ProcessID);if(modules==INVALID_HANDLE_VALUE)continue;MODULEENTRY32W module{};module.dwSize=sizeof(module);if(Module32FirstW(modules,&module))do{if(!_wcsicmp(module.szExePath,path.c_str())){busy=true;break;}}while(Module32NextW(modules,&module));CloseHandle(modules);if(busy)break;}while(Process32NextW(processes,&process));CloseHandle(processes);return busy;}
